package com.yuegang.zhihui.training.application;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.training.api.*;import com.yuegang.zhihui.training.api.LearningPathView.PathCourseView;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;public final class LearningPathService{private final JdbcTemplate jdbc;public LearningPathService(DataSource d){jdbc=new JdbcTemplate(d);}public LearningPathView create(SaveLearningPathRequest r){long id=next();jdbc.update("INSERT INTO training_learning_path(id,position_code,name) VALUES(?,?,?)",id,r.positionCode(),r.name());return get(id);}public LearningPathView addCourse(String path,AddPathCourseRequest r){long id=id(path);jdbc.update("INSERT INTO training_path_course(path_id,course_id,sequence_no,prerequisite_course_id) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE sequence_no=VALUES(sequence_no),prerequisite_course_id=VALUES(prerequisite_course_id)",id,id(r.courseId()),r.sequenceNo(),optional(r.prerequisiteCourseId()));return get(id);}public List<LearningPathView>byPosition(String position){return jdbc.queryForList("SELECT id FROM training_learning_path WHERE position_code=? AND enabled=TRUE ORDER BY id",Long.class,position).stream().map(this::get).toList();}public List<LearningPathView>all(){return jdbc.queryForList("SELECT id FROM training_learning_path ORDER BY position_code,id",Long.class).stream().map(this::get).toList();}private LearningPathView get(long id){return jdbc.query("SELECT id,position_code,name,enabled,version FROM training_learning_path WHERE id=?",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);List<PathCourseView>courses=jdbc.query("SELECT course_id,sequence_no,prerequisite_course_id FROM training_path_course WHERE path_id=? ORDER BY sequence_no",(x,n)->{Object p=x.getObject(3);return new PathCourseView(Long.toString(x.getLong(1)),x.getInt(2),p==null?null:p.toString());},id);return new LearningPathView(Long.toString(r.getLong(1)),r.getString(2),r.getString(3),r.getBoolean(4),r.getLong(5),courses);},id);}private static Long optional(String x){return x==null||x.isBlank()?null:id(x);}private static long id(String x){try{long v=Long.parseLong(x);if(v<=0)throw new NumberFormatException();return v;}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}}
